parameters.jsCode:
const text = $input.first().json.result.content[0].text;
const data = JSON.parse(text);
const g = (data.data ? data.data.goalItemById : data.goalItemById) || {};
const dryRun = String(($('Webhook').first().json.query.dryRun) || '') === '1';
return [{ json: { goalId: $('Webhook').first().json.query.goal_id,
  body: g.body || '', contribution: g.contribution || '', tags: g.tags || [], dryRun } }];

// Window = last waHours (default 24). Rows arrive once per ACCOUNT: a message in a group both numbers belong
// to is logged twice with the same WhatsApp msgId -> dedupe on msgId|chatId and remember both accounts.
const TZ = 'America/New_York';
const ACC = {"919913296665": "IN", "18483918889": "US"};
const hours = Math.max(1, Number(($('Webhook').first().json.query.waHours) || 24));
const now = Date.now(), since = now - hours * 3600e3;
// ts may come back as an ISO string or (if Sheets auto-typed the cell) a serial day number
const tsOf = r => typeof r.ts === 'number' ? Math.round((r.ts - 25569) * 86400e3) : Date.parse(r.ts);
const rows = $input.all().map(i => i.json).filter(r => r && r.msgId && r.ts && !r.error)
  .map(r => Object.assign({}, r, { msgId: String(r.msgId), account: String(r.account), chatId: String(r.chatId),
    author: String(r.author == null ? '' : r.author), text: String(r.text == null ? '' : r.text), _t: tsOf(r) }))
  .filter(r => isFinite(r._t));
const win = rows.filter(r => r._t >= since && r._t <= now + 3600e3).sort((a, b) => a._t - b._t);
const seen = {}, uniq = [];
for (const r of win) {
  const k = r.msgId + '|' + r.chatId;
  if (seen[k]) { seen[k].accounts[r.account] = 1; continue; }
  const e = Object.assign({}, r, { accounts: { [r.account]: 1 } }); seen[k] = e; uniq.push(e);
}
const hhmm = t => new Date(t).toLocaleTimeString('en-US', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false });
const chats = {};
for (const r of uniq) {
  const isStatus = r.chatType === 'status';
  const id = isStatus ? 'status' : r.chatId;
  const c = chats[id] || (chats[id] = { chatId: id, chatName: isStatus ? 'Status updates' : r.chatName, chatType: r.chatType,
    accounts: {}, messages: 0, reactions: 0, authors: {}, lines: [], lastTs: 0, lastFromMe: false, myMsgs: 0 });
  Object.assign(c.accounts, r.accounts);
  if (r.kind === 'reaction') { c.reactions++; continue; }
  c.messages++; c.authors[r.author] = (c.authors[r.author] || 0) + 1;
  if (r.fromMe === 'yes') c.myMsgs++;
  const t = r._t;
  if (t >= c.lastTs) { c.lastTs = t; c.lastFromMe = r.fromMe === 'yes'; }
  if (!isStatus) c.lines.push(hhmm(t) + ' ' + r.author + ': ' + String(r.text || '').slice(0, 240) + (r.quoted ? ' (re: "' + String(r.quoted).slice(0, 60) + '")' : ''));
}
const label = a => ACC[a] || a;
const order = { dm: 0, group: 1, status: 2 };
const list = Object.values(chats).map(c => {
  const topAuthors = Object.entries(c.authors).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([n, k]) => n + ' (' + k + ')');
  return { chatId: c.chatId, chatName: c.chatName, chatType: c.chatType,
    accounts: Object.keys(c.accounts).map(label).sort(), messages: c.messages, reactions: c.reactions,
    participants: Object.keys(c.authors).length, topAuthors, myMsgs: c.myMsgs, lastFromMe: c.lastFromMe,
    lastAt: c.lastTs ? new Date(c.lastTs).toISOString() : '', lines: c.lines.slice(-60) };
}).sort((a, b) => (order[a.chatType] - order[b.chatType]) || (b.messages - a.messages));
// transcripts for the LLM, total budget ~26k chars
let budget = 26000;
const forLLM = [];
for (const c of list) {
  if (c.chatType === 'status' || !c.lines.length) continue;
  let tr = c.lines.join('\n'); if (tr.length > 3500) tr = '...\n' + tr.slice(-3500);
  if (tr.length > budget) { tr = tr.slice(-Math.max(0, budget)); if (!tr) break; }
  budget -= tr.length;
  forLLM.push({ chatId: c.chatId, chatName: c.chatName, chatType: c.chatType, accounts: c.accounts,
    messages: c.messages, lastFromMe: c.lastFromMe, transcript: tr });
}
const stats = { hours, since: new Date(since).toISOString(), rawRows: win.length, unique: uniq.length,
  duplicatesMerged: win.length - uniq.length, logRows: rows.length,
  groups: list.filter(c => c.chatType === 'group').length, dms: list.filter(c => c.chatType === 'dm').length,
  statusUpdates: (list.find(c => c.chatType === 'status') || {}).messages || 0 };
return [{ json: { stats, chats: list.map(c => Object.assign({}, c, { lines: undefined })), forLLM } }];

// Merge WhatsApp buckets with Instagram DM conversations (upload-post) and LinkedIn conversations
// (ConnectSafely) into ONE uniform chat list + one LLM transcript bundle. Same `hours` window as WhatsApp.
const TZ = 'America/New_York', IG_SELF = 'grvpanchal';
const WA = $('WA Consolidate').first().json;
const hours = WA.stats.hours, now = Date.now(), since = Date.parse(WA.stats.since);
const hhmm = t => new Date(t).toLocaleTimeString('en-US', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false });
const iso = s => Date.parse(String(s || '').replace(/([+-]\d{2})(\d{2})$/, '$1:$2'));   // IG uses +0000
const clip = (s, n) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().slice(0, n);
const errOf = j => (j && j.error) ? clip(j.error.message || j.error.description || JSON.stringify(j.error), 160) : '';
const grab = n => { try { return $(n).first().json || {}; } catch (e) { return {}; } };

// ---- Instagram ----
const igJ = grab('IG DMs'); const igError = errOf(igJ) || (igJ.success === false ? clip(igJ.message || 'upload-post returned success:false', 160) : '');
const ig = [];
for (const c of (igJ.conversations || [])) {
  const parts = ((c.participants || {}).data || []).map(p => p.username).filter(u => u && u !== IG_SELF);
  const msgs = ((c.messages || {}).data || []).map(m => Object.assign({}, m, { _t: iso(m.created_time) })).filter(m => isFinite(m._t)).sort((a, b) => a._t - b._t);
  if (!msgs.length) continue;
  const recent = msgs.filter(m => m._t >= since);
  if (!recent.length) continue;                                    // nothing new in the window
  const text = m => clip(m.message, 240) || (m.shares && m.shares.length ? '[shared ' + (m.shares[0].link || 'post') + ']'
    : (m.story ? '[story ' + ((m.story.mention && 'mention') || (m.story.reply_to && 'reply') || 'share') + ']' : (m.attachments ? '[attachment]' : '[media]')));
  const authors = {}; let myMsgs = 0;
  recent.forEach(m => { const u = (m.from || {}).username === IG_SELF ? 'Me' : ((m.from || {}).username || '?'); authors[u] = (authors[u] || 0) + 1; if (u === 'Me') myMsgs++; });
  const last = msgs[msgs.length - 1];
  ig.push({ channel: 'instagram', chatId: 'ig:' + c.id, chatName: parts.join(', ') || 'Instagram chat', chatType: parts.length > 1 ? 'group' : 'dm',
    accounts: ['IG'], messages: recent.length, reactions: 0, participants: Object.keys(authors).length,
    topAuthors: Object.entries(authors).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([n, k]) => n + ' (' + k + ')'),
    myMsgs, lastFromMe: (last.from || {}).username === IG_SELF, lastAt: new Date(last._t).toISOString(),
    lines: msgs.slice(-12).map(m => hhmm(m._t) + ' ' + ((m.from || {}).username === IG_SELF ? 'Me' : (m.from || {}).username) + ': ' + text(m)) });
}

// ---- LinkedIn ----
const liJ = grab('LI Messages'); const liError = errOf(liJ) || (liJ.success === false ? clip(liJ.message || liJ.error || 'ConnectSafely returned success:false', 160) : '');
const li = [];
for (const c of (liJ.conversations || [])) {
  const t = Date.parse(c.lastActivityAt || ''); const unread = Number(c.unreadCount) || 0;
  if (!(t >= since) && !unread) continue;                          // new activity OR still unread
  const names = (c.participants || []).map(p => p.name).filter(Boolean);
  const head = (c.participants || []).map(p => p.headline).filter(Boolean)[0] || '';
  const lm = c.latestMessage || {};
  li.push({ channel: 'linkedin', chatId: 'li:' + (c.conversationId || c.conversationUrn), chatName: names.join(', ') || 'LinkedIn chat',
    chatType: names.length > 1 ? 'group' : 'dm', accounts: ['LI'], messages: unread || (t >= since ? 1 : 0), reactions: 0,
    participants: names.length, topAuthors: names.slice(0, 5), myMsgs: 0, unread, headline: clip(head, 100),
    lastFromMe: !unread && !(t >= since), lastAt: isFinite(t) ? new Date(t).toISOString() : '',
    lines: [(isFinite(t) ? hhmm(t) + ' ' : '') + (names[0] || 'Them') + (head ? ' (' + clip(head, 80) + ')' : '') + ': ' + (clip(lm.text, 600) || '[no text / attachment]') + (unread ? '  [UNREAD x' + unread + ']' : '')] });
}

// ---- merge: WhatsApp (already consolidated) + IG + LI ----
const waChats = (WA.chats || []).map(c => Object.assign({ channel: 'whatsapp' }, c));
const chats = waChats.concat(ig, li);
let budget = 30000; const forLLM = [];
for (const c of (WA.forLLM || []).map(x => Object.assign({ channel: 'whatsapp' }, x)).concat(ig.concat(li).map(c => ({
    channel: c.channel, chatId: c.chatId, chatName: c.chatName, chatType: c.chatType, accounts: c.accounts, messages: c.messages,
    lastFromMe: c.lastFromMe, unread: c.unread || 0, transcript: c.lines.join('\n') })))) {
  let tr = String(c.transcript || ''); if (tr.length > 3500) tr = '...\n' + tr.slice(-3500);
  if (tr.length > budget) { tr = tr.slice(-Math.max(0, budget)); if (!tr) break; }
  budget -= tr.length; forLLM.push(Object.assign({}, c, { transcript: tr }));
}
const stats = Object.assign({}, WA.stats, { igChats: ig.length, igError, liChats: li.length, liUnread: li.reduce((s, c) => s + (c.unread || 0), 0), liError });
return [{ json: { stats, chats: chats.map(c => Object.assign({}, c, { lines: undefined })), forLLM } }];

const TZ = 'America/New_York';
const extractJson = (s) => {
  s = String(s || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(s); } catch (e) {}
  const i = s.indexOf('{'); if (i < 0) return null;
  let depth = 0, inStr = false, esc = false;
  for (let k = i; k < s.length; k++) { const ch = s[k];
    if (esc) { esc = false; continue; }
    if (inStr) { if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') { inStr = true; continue; }
    if (ch === '{') depth++; else if (ch === '}') { depth--; if (!depth) { try { return JSON.parse(s.slice(i, k + 1)); } catch (e) { return null; } } } }
  return null;
};
const C = $('Msg Consolidate').first().json;
let llm = null, llmError = '';
try { const r = $input.first().json; if (r && r.error) llmError = String(r.error.message || r.error).slice(0, 160);
  llm = extractJson(r && r.choices ? r.choices[0].message.content : ''); } catch (e) { llmError = String(e.message || e); }
llm = llm || { overall: '', chats: [] };
const byId = {}; (llm.chats || []).forEach(c => { if (c && c.chatId) byId[String(c.chatId)] = c; });
const arr = x => Array.isArray(x) ? x.map(s => String(s).trim()).filter(Boolean) : (x ? [String(x)] : []);
const chats = (C.chats || []).map(c => {
  const s = byId[c.chatId] || {};
  const summary = String(s.summary || '').trim() || (c.chatType === 'status'
    ? c.messages + ' status update(s) from ' + c.topAuthors.join(', ')
    : (!c.messages && c.reactions ? 'Only ' + c.reactions + ' reaction(s) to older messages, nothing new.'
       : c.messages + ' message(s)' + (c.reactions ? ', ' + c.reactions + ' reaction(s)' : '') + ' - no summary available'));
  const replyable = c.chatType === 'dm' && !c.lastFromMe && (c.channel !== 'linkedin' || (c.unread || 0) > 0);
  return Object.assign({}, c, { summary, highlights: arr(s.highlights), actionItems: arr(s.actionItems),
    needsReply: !!s.needsReply && replyable, reply: String(s.reply || '').trim() });
});
const now = new Date(); const dayKey = now.toLocaleDateString('en-CA', { timeZone: TZ });
const rows = chats.map(c => ({ key: dayKey + '|' + c.chatId, dayKey, chatName: c.chatName,
  chatType: c.channel === 'whatsapp' ? c.chatType : c.channel + ' ' + c.chatType,
  accounts: c.accounts.join('+'), messages: c.messages, reactions: c.reactions, participants: c.participants,
  topAuthors: c.topAuthors.join(', '), summary: c.summary, highlights: c.highlights.join(' • '),
  actionItems: c.actionItems.join(' • '), needsReply: c.needsReply ? 'yes' : 'no', suggestedReply: c.reply,
  updatedAt: now.toISOString() }));
return [{ json: { dayKey, overall: String(llm.overall || '').trim(), llmError, stats: C.stats, chats, rows } }];

// tolerant JSON extraction (same gotcha as CMO: models append garbage / fences)
const extractJson = (s) => {
  s = String(s || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(s); } catch (e) {}
  const i = s.indexOf('{');
  if (i < 0) return null;
  let depth = 0, inStr = false, esc = false;
  for (let k = i; k < s.length; k++) {
    const ch = s[k];
    if (esc) { esc = false; continue; }
    if (inStr) { if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') { inStr = true; continue; }
    if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (!depth) { try { return JSON.parse(s.slice(i, k + 1)); } catch (e) { return null; } } }
  }
  return null;
};
let plan = null;
try { const c = $('Draft Replies').first().json; plan = extractJson(c && c.choices ? c.choices[0].message.content : ''); } catch (e) {}
plan = plan || { focus: '', gmail: [], other: [] };
const dryRun = $('Parse Goal').first().json.dryRun;
// fill to/subject from the real inbox item when the model omits them (Gmail node fields are From/Subject)
const byId = {}; try { $('Gmail Unread').all().forEach(i => { if (i.json && i.json.id) { byId[i.json.id] = i.json; byId['t:' + i.json.threadId] = i.json; } }); } catch (e) {}
(plan.gmail || []).forEach(g => { const i = byId[g.id] || byId['t:' + g.threadId]; if (!i) return;
  const em = String(i.From || '').match(/<([^>]+)>/); g.to = g.to || (em ? em[1] : String(i.From || '').trim()); g.subject = g.subject || i.Subject || ''; });
const drafts = (plan.gmail || []).filter(g => g && !g.skip && g.reply && g.threadId && g.to);
if (dryRun || !drafts.length) return [{ json: { noDrafts: true, plan } }];
return drafts.map(d => ({ json: { ...d, noDrafts: false, plan } }));

const P = $('Parse Goal').first().json;
const grab = (n) => { try { return $(n).all().map(i => i.json); } catch (e) { return []; } };
let plan = { focus: '', gmail: [], other: [] };
try { plan = $('Parse Drafts').first().json.plan || plan; } catch (e) {}
const created = grab('Create Draft').filter(d => d && !d.error).length;
const gmailErr = (() => { try { const g = $('Gmail Unread').first().json; return g && g.error ? String(g.error.message || g.error).slice(0,120) : ''; } catch (e) { return ''; } })();

const L = ['# Response Desk'];

// ---- Gmail: join the model's verdicts back to the real inbox items (model often omits subject/from) ----
const inbox = grab('Gmail Unread').filter(i => i && i.id);
const byMail = {}; inbox.forEach(i => { byMail[i.id] = i; if (i.threadId) byMail['t:' + i.threadId] = i; });
const fromOf = i => String((i && (i.From || (i.from && (i.from.text || i.from)))) || '');   // "Name <addr>"
const senderOf = i => { const f = fromOf(i); const m = f.match(/^"?([^"<]+?)"?\s*<[^>]+>/); return (m ? m[1] : f.replace(/<[^>]*>/g, '')).trim(); };
const gm = (plan.gmail || []).map(g => { const i = byMail[g.id] || byMail['t:' + g.threadId] || {};
  const em = fromOf(i).match(/<([^>]+)>/);
  return Object.assign({}, g, { subject: g.subject || i.Subject || i.subject || '(no subject)', sender: senderOf(i) || g.to || '', to: g.to || (em ? em[1] : '') }); });
const act = gm.filter(g => !g.skip).sort((a,b) => (a.priority||9) - (b.priority||9));
const skipped = gm.filter(g => g.skip);
const one = s => String(s || '').replace(/\s+/g, ' ').trim();

const byCh = {};
(plan.other || []).forEach(o => { (byCh[String(o.channel||'other').toLowerCase()] = byCh[String(o.channel||'other').toLowerCase()] || []).push(o); });

// ---- WhatsApp digest (both accounts, shared groups consolidated) ----
let W = { dayKey: '', overall: '', llmError: '', stats: {}, chats: [], rows: [] };
try { W = $('WA Parse').first().json || W; } catch (e) {}
const S = W.stats || {};
const meta = c => c.accounts.join('+') + ' · ' + c.messages + ' msg' + (c.reactions ? ' · ' + c.reactions + ' react' : '') + (c.participants > 1 ? ' · ' + c.participants + ' people' : '');
const chatLine = c => {
  let s = '- **' + one(c.chatName) + '** (' + meta(c) + '): ' + one(c.summary);
  if (c.highlights.length) s += '\n  • ' + c.highlights.map(one).join('\n  • ');
  if (c.actionItems.length) s += '\n  → ' + c.actionItems.map(one).join('; ');
  return s;
};
// ---- 1. Overview first ----
const allNeed = W.chats.filter(c => c.needsReply);
const ov = ['## Messages today'];
if (W.overall) ov.push(one(W.overall));
if (plan.focus) ov.push(one(plan.focus));
const needList = act.map(g => g.subject + ' · gmail').concat(allNeed.map(c => c.chatName + ' · ' + c.channel));
ov.push(needList.length ? '**' + needList.length + ' reply/replies needed:** ' + needList.join('; ') : '**No replies needed.**');
ov.push('Gmail ' + gm.length + ' unread · WhatsApp ' + (S.unique || 0) + ' events · Instagram ' + (S.igChats || 0) + ' chat(s) · LinkedIn ' + (S.liChats || 0) + ' chat(s)' + (S.liUnread ? ' (' + S.liUnread + ' unread)' : ''));
if (W.llmError) ov.push('(summary model error: ' + W.llmError + ' - counts are exact, summaries are fallbacks)');
L.push(ov.join('\n'));

// ---- 2. Gmail ----
L.push('## Gmail (grvpanchal@gmail.com)');
if (gmailErr) L.push('Inbox fetch failed: ' + gmailErr);
if (!gm.length && !gmailErr) L.push('No unread inbox mail.');
if (act.length) {
  L.push('### Needs reply (' + act.length + ')');
  act.forEach(g => L.push('- **P' + (g.priority||3) + ' · ' + one(g.subject) + '** — ' + one(g.sender) + (g.to && g.to !== g.sender ? ' <' + g.to + '>' : '')
    + (P.dryRun ? ' · dryRun, draft NOT created' : (created ? ' · reply draft in Gmail' : ''))
    + '\n  Draft: ' + one(g.reply)));
}
if (skipped.length) {
  L.push('### Skipped, no reply needed (' + skipped.length + ')');
  skipped.forEach(g => L.push('- **' + one(g.subject) + '** — ' + one(g.sender) + (g.reason ? ' · ' + one(g.reason) : '')));
}

const section = (title, chans, emptyMsg, extra) => {
  const cs = W.chats.filter(c => chans.includes(c.channel));
  L.push('## ' + title);
  if (extra) L.push(extra);
  if (!cs.length) { L.push(emptyMsg); return; }
  const need = cs.filter(c => c.needsReply);
  if (need.length) { L.push('### Needs reply'); need.forEach(c => L.push(chatLine(c) + '\n  Draft: ' + one(c.reply))); }
  const dms = cs.filter(c => c.chatType === 'dm' && !c.needsReply);
  if (dms.length) { L.push('### Direct chats'); dms.forEach(c => L.push(chatLine(c))); }
  const groups = cs.filter(c => c.chatType === 'group' && !c.needsReply);
  if (groups.length) { L.push('### Groups'); groups.forEach(c => L.push(chatLine(c))); }
  const st = cs.find(c => c.chatType === 'status');
  if (st) L.push('### Status\n- ' + st.messages + ' update(s): ' + st.topAuthors.join(', '));
};

section('WhatsApp (IN +91 99132 96665 · US +1 848 391 8889)', ['whatsapp'],
  'No WhatsApp activity in the last ' + (S.hours || 24) + 'h' + (S.logRows === 0 ? ' - log is empty, is the WA-Sync extension running on both numbers?' : '') + '.',
  'Last ' + (S.hours || 24) + 'h: ' + (S.unique || 0) + ' events across ' + (S.groups || 0) + ' group(s), ' + (S.dms || 0) + ' direct chat(s), '
    + (S.statusUpdates || 0) + ' status update(s)' + (S.duplicatesMerged ? ' - ' + S.duplicatesMerged + ' duplicate(s) from groups on both numbers merged' : '') + '. [Daily sheet](https://docs.google.com/spreadsheets/d/<<REPLACE_ME>>/edit#gid=1676281074)');
(byCh.whatsapp || []).forEach(o => L.push('- Pasted: ' + (o.context||'') + '\n  Draft: ' + String(o.reply||'').replace(/\n/g,' ')));

section('Instagram DMs (@grvpanchal via upload-post)', ['instagram'],
  S.igError ? 'Fetch failed: ' + S.igError : 'No new Instagram DMs in the last ' + (S.hours || 24) + 'h.');
(byCh.instagram || []).forEach(o => L.push('- Pasted: ' + (o.context||'') + '\n  Draft: ' + String(o.reply||'').replace(/\n/g,' ')));

section('LinkedIn messages (via ConnectSafely)', ['linkedin'],
  S.liError ? 'Fetch failed: ' + S.liError + (/INVALID_ACCOUNT|404/.test(S.liError) ? ' (LinkedIn reconnected? accountId changes - check GET /accounts)' : '')
            : 'No new or unread LinkedIn messages in the last ' + (S.hours || 24) + 'h.');
(byCh.linkedin || []).forEach(o => L.push('- Pasted: ' + (o.context||'') + '\n  Draft: ' + String(o.reply||'').replace(/\n/g,' ')));

const base = String(P.contribution || '').replace(/(^|\n)# Response Desk[\s\S]*$/, '').trim();   // section may be at pos 0
const newContribution = (base ? base + '\n\n---\n\n' : '') + L.join('\n\n');
return [{ json: { goalId: P.goalId, newContribution, summary: {
  gmailUnread: gm.length, replyDrafts: act.length, draftsCreatedInGmail: created,
